\[\begin{aligned}
G\frac{M_T m}{r_0^2} &= m\frac{v_0^2}{r_0} \\
v_0 &= \frac{2\pi r_0}{T_0} \\
g &= \frac{GM_T}{R_T^2}
\end{aligned}
\quad\Rightarrow\quad
\begin{aligned}
r_0 &= \left(\frac{gR_T^2T_0^2}{4\pi^2}\right)^{1/3} \quad\Rightarrow\quad r_0 = 4.22\cdot 10^7\,\mathrm{m} \\
v_0 &= R_T\sqrt{\frac{g}{r_0}} \quad\Rightarrow\quad v_0 = 3.07\cdot 10^3\,\mathrm{m/s}
\end{aligned}\]
